function escHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatTime(seconds) {
  if (!isFinite(seconds) || seconds <= 0) return '瞬间';
  if (seconds < 1) return '< 1 秒';
  if (seconds < 60) return Math.round(seconds) + ' 秒';
  if (seconds < 3600) return Math.round(seconds / 60) + ' 分钟';
  if (seconds < 86400) return Math.round(seconds / 3600) + ' 小时';
  if (seconds < 86400 * 30) return Math.round(seconds / 86400) + ' 天';
  if (seconds < 86400 * 365) return Math.round(seconds / 86400 / 30) + ' 个月';
  const years = seconds / 86400 / 365;
  if (years < 1e3) return Math.round(years) + ' 年';
  if (years < 1e6) return Math.round(years / 1e3) + ' 千年';
  if (years < 1e9) return Math.round(years / 1e6) + ' 百万年';
  if (years < 1e12) return Math.round(years / 1e9) + ' 十亿年';
  if (years < 1e15) return Math.round(years / 1e12) + ' 万亿年';
  const log10 = Math.log10(years);
  if (log10 < 30) return '10^' + Math.round(log10 * 10) / 10 + ' 年';
  return '10^' + Math.floor(log10) + ' 年';
}

const COMMON = [
  '123456', 'password', '123456789', '12345678', '12345', '111111', '1234567',
  'sunshine', 'qwerty', 'iloveyou', 'princess', 'admin', 'welcome', '666666',
  'abc123', 'football', '123123', 'monkey', '654321', '!@#$%^&*', 'charlie',
  'aa123456', 'donald', 'password1', 'qwerty123', '11111111', '000000',
  'letmein', 'dragon', 'baseball', 'shadow', 'master', 'michael'
];
const COMMON_SET = new Set(COMMON);

const KEYBOARD_ROWS = [
  'qwertyuiop', 'asdfghjkl', 'zxcvbnm',
  '1234567890', '0987654321',
  '!@#$%^&*()', ')(*&^%$#!'
];

function hasSequential(pw) {
  if (pw.length < 4) return null;
  const lower = pw.toLowerCase();
  for (let i = 0; i <= lower.length - 4; i++) {
    const sub = lower.slice(i, i + 4);
    for (const row of KEYBOARD_ROWS) {
      if (row.indexOf(sub) >= 0) return sub;
    }
  }
  for (let i = 0; i <= pw.length - 4; i++) {
    let asc = true, desc = true;
    for (let j = 1; j < 4; j++) {
      const a = pw.charCodeAt(i + j - 1);
      const b = pw.charCodeAt(i + j);
      if (b - a !== 1) asc = false;
      if (a - b !== 1) desc = false;
    }
    if (asc || desc) return pw.slice(i, i + 4);
  }
  return null;
}

function hasRepeats(pw) {
  if (pw.length < 3) return null;
  const m = pw.match(/(.)\1{2,}/);
  if (m) return m[0];
  const m2 = pw.match(/(..)\1{2,}/);
  if (m2) return m2[0];
  return null;
}

function calcEntropy(pw) {
  if (!pw) return 0;
  let pool = 0;
  if (/[a-z]/.test(pw)) pool += 26;
  if (/[A-Z]/.test(pw)) pool += 26;
  if (/[0-9]/.test(pw)) pool += 10;
  if (/[^a-zA-Z0-9\s]/.test(pw)) pool += 32;
  if (/\s/.test(pw)) pool += 1;
  if (pool === 0) return 0;
  return pw.length * Math.log2(pool);
}

function scorePassword(pw) {
  const issues = [];
  const positives = [];

  if (!pw) {
    return { score: 0, level: '请输入密码', color: '#9ca3af', issues, positives, entropy: 0, hasLower: false, hasUpper: false, hasDigit: false, hasSpecial: false };
  }

  let score = 0;

  if (pw.length >= 8) score += 1;
  if (pw.length >= 12) score += 1;
  if (pw.length >= 16) score += 1;
  if (pw.length < 8) issues.push('密码长度不足 8 位（建议 ≥ 12 位）');

  if (pw.length >= 12) positives.push('长度 ≥ 12 位');

  const hasLower = /[a-z]/.test(pw);
  const hasUpper = /[A-Z]/.test(pw);
  const hasDigit = /[0-9]/.test(pw);
  const hasSpecial = /[^a-zA-Z0-9]/.test(pw);
  const classes = [hasLower, hasUpper, hasDigit, hasSpecial].filter(Boolean).length;
  if (classes >= 3) score += 1;
  if (classes === 4) positives.push('包含 4 种字符类型');
  if (classes < 3) issues.push('字符种类不足（建议大小写+数字+特殊）');

  if (COMMON_SET.has(pw.toLowerCase())) {
    score = Math.max(0, score - 2);
    issues.push('⚠️ 这是常见弱密码，请勿使用');
  }

  const seq = hasSequential(pw);
  if (seq) {
    score = Math.max(0, score - 1);
    issues.push('包含键盘序列或连续字符：' + seq);
  }

  const rep = hasRepeats(pw);
  if (rep) {
    score = Math.max(0, score - 1);
    issues.push('包含重复模式：' + rep);
  }

  const entropy = calcEntropy(pw);
  if (entropy >= 60) positives.push('熵值 ≥ 60 bits');
  if (entropy < 36) issues.push('熵值过低（<' + Math.round(entropy) + ' bits）');

  score = Math.min(4, Math.max(0, score));

  let level, color;
  if (score === 0) { level = '极弱'; color = '#ef4444'; }
  else if (score === 1) { level = '弱'; color = '#f97316'; }
  else if (score === 2) { level = '一般'; color = '#f59e0b'; }
  else if (score === 3) { level = '良好'; color = '#3b82f6'; }
  else { level = '强'; color = '#22c55e'; }

  if (pw.length < 16) issues.push('建议使用 16 位以上随机字符');
  if (!hasSpecial) issues.push('建议加入特殊字符（!@#$% 等）');
  if (/^[a-zA-Z]+$/.test(pw)) issues.push('建议混入数字和特殊字符');

  return { score, level, color, issues, positives, entropy, hasLower, hasUpper, hasDigit, hasSpecial };
}

