      + '🛡️ 查询由 <a href="https://haveibeenpwned.com/Passwords" target="_blank" rel="noopener" style="color:var(--primary);">Have I Been Pwned</a> 提供，k-anonymity 模型确保完整哈希不会离开您的设备。'
      + '</div>';
    output.innerHTML = html;
    status.innerHTML = count > 0 ? '❌ 查询完成，发现 ' + count.toLocaleString() + ' 次泄露记录' : '✅ 查询完成，未发现泄露';
  } catch (e) {
    output.innerHTML = '<div style="padding:1rem;text-align:center;color:#ef4444;">❌ 查询失败：' + e.message + '<br><span style="font-size:0.8rem;opacity:0.7;">请检查网络连接或稍后重试</span></div>';
    status.innerHTML = '❌ 查询失败';
  } finally {
