function splitWords(s) {
  if (!s) return [];
  return s
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/[\s_\-]+/g, ' ')
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);
}

function toCamel(words) {
  if (!words.length) return '';
  return words[0] + words.slice(1).map(w => w[0].toUpperCase() + w.slice(1)).join('');
}
function toSnake(words) { return words.join('_'); }
function toKebab(words) { return words.join('-'); }
function toPascal(words) { return words.map(w => w[0].toUpperCase() + w.slice(1)).join(''); }
function toConst(words) { return words.map(w => w.toUpperCase()).join('_'); }

function run(mode) {
  const v = input.value;
  if (!v.trim()) { output.textContent = ''; preview.innerHTML = ''; return; }
  const words = splitWords(v);
  if (!words.length) { output.textContent = '无法识别输入'; preview.innerHTML = ''; return; }
  const results = {
    camelCase: toCamel(words),
    snake_case: toSnake(words),
    PascalCase: toPascal(words),
    'kebab-case': toKebab(words),
    CONST_CASE: toConst(words),
  };
  output.textContent = results[mode] || '';
  preview.innerHTML = Object.entries(results).map(([k, val]) =>
    '<div style="background:var(--bg-secondary);padding:0.5rem 0.75rem;border-radius:8px;"><div style="opacity:0.6;font-size:0.75rem;">' + k + '</div><div style="font-family:monospace;font-weight:600;color:' + (k === mode ? 'var(--primary)' : 'var(--text)') + ';">' + val + '</div></div>'
  ).join('');
}

