});

function generate() {
  const text = (charsEl.value || '').replace(/\s+/g, '').slice(0, 100);
  if (!text) { alert('请输入汉字'); return; }
  const rowsPerPage = Math.max(4, Math.min(20, parseInt(rowsPerPageEl.value) || 10));
  const charsPerRow = Math.max(4, Math.min(12, parseInt(charsPerRowEl.value) || 6));
  const fontSize = parseInt(fontSizeEl.value) || 48;
  const cellStyle = cellStyleEl.value;
  const cellSize = Math.round(fontSize * 1.4);
  const chars = text.split('');
  const perPage = rowsPerPage * charsPerRow;
  const pageCount = Math.ceil(chars.length / perPage);
  let html = '';
  for (let p = 0; p < pageCount; p++) {
    html += '<div class="worksheet-page">';
    html += '<div class="worksheet-title">汉字描红字帖</div>';
    html += '<div class="worksheet-subtitle">第 ' + (p + 1) + ' / ' + pageCount + ' 页 · 共 ' + chars.length + ' 字</div>';
    const pageChars = chars.slice(p * perPage, (p + 1) * perPage);
    for (let r = 0; r < rowsPerPage; r++) {
      html += '<div class="cell-row">';
      for (let c = 0; c < charsPerRow; c++) {
        const ch = pageChars[r * charsPerRow + c];
        if (ch) {
          html += '<span class="cell ' + cellStyle + '" style="width:' + cellSize + 'px;height:' + cellSize + 'px;font-size:' + fontSize + 'px;">' + ch + '</span>';
        } else {
          html += '<span class="cell ' + cellStyle + '" style="width:' + cellSize + 'px;height:' + cellSize + 'px;"></span>'
        }
      }
      html += '</div>';
    }
    html += '</div>';
  }
  worksheet.innerHTML = html;
  worksheetWrap.style.display = '';
  pageInfo.textContent = '共 ' + pageCount + ' 页 · ' + chars.length + ' 字';
}

generateBtn.addEventListener('click', generate);
printBtn.addEventListener('click', () => window.print());
clearBtn.addEventListener('click', () => { charsEl.value = ''; worksheetWrap.style.display = 'none'; worksheet.innerHTML = ''; });
generate();

