let cur = null;
let answered = 0;
let correct = 0;

function pickQuestion() {
  const cats = Array.from(document.querySelectorAll('.catFilter:checked')).map(c => c.value);
  const pool = QUESTIONS.filter(q => cats.includes(q.cat));
  if (!pool.length) return null;
  let next;
  do { next = pool[Math.floor(Math.random() * pool.length)]; } while (next === cur && pool.length > 1);
  return next;
}

function renderQuestion() {
  cur = pickQuestion();
  if (!cur) {
    document.getElementById('questionArea').textContent = '请至少选择一个分类';
    return;
  }
  const display = cur.q.replace('____', ' ____ ');
  document.getElementById('questionArea').innerHTML = '<span style="opacity:0.65;font-size:0.85rem;">[' + cur.cat + '类]</span><br><br>' + display;
  document.getElementById('userAnswer').value = '';
  document.getElementById('result').style.display = 'none';
  document.getElementById('explanation').style.display = 'none';
}

function check() {
  if (!cur) return;
  const userAns = document.getElementById('userAnswer').value.trim();
  const result = document.getElementById('result');
  const ok = userAns === cur.full;
  result.style.display = '';
  result.style.background = ok ? '#dcfce7' : '#fee2e2';
  result.style.color = ok ? '#15803d' : '#b91c1c';
  result.innerHTML = ok
    ? '✅ 回答正确！成语是：<b>' + cur.full + '</b>'
    : '❌ 回答错误。你的答案：<b>' + userAns + '</b><br>正确答案：<b>' + cur.full + '</b>';
  answered++;
  if (ok) correct++;
  document.getElementById('answeredCount').textContent = answered;
  document.getElementById('correctCount').textContent = correct;
}

document.getElementById('newQuestion').addEventListener('click', renderQuestion);
document.getElementById('showAnswer').addEventListener('click', () => {
  if (!cur) return;
  const r = document.getElementById('result');
  r.style.display = '';
  r.style.background = '#dbeafe';
  r.style.color = '#1e40af';
  r.innerHTML = '💡 答案：<b>' + cur.full + '</b>';
});
document.getElementById('showExplanation').addEventListener('click', () => {
