const searchInput = document.getElementById('searchInput');
const randomBtn = document.getElementById('randomBtn');
const resultList = document.getElementById('resultList');
const stats = document.getElementById('stats');

function getFiltered() {
  const cats = Array.from(document.querySelectorAll('.catFilter:checked')).map(c => c.value);
  const q = searchInput.value.trim().toLowerCase();
  return XIEHOUYU.filter(x => {
    if (!cats.includes(x.cat)) return false;
    if (q && !(x.front.toLowerCase().includes(q) || x.back.toLowerCase().includes(q) || x.exp.includes(q))) return false;
    return true;
  });
}

function render() {
  const list = getFiltered();
  stats.textContent = '共找到 ' + list.length + ' 条歇后语';
  if (!list.length) {
    resultList.innerHTML = '<div style="text-align:center;padding:2rem;opacity:0.6;">没有匹配的歇后语</div>';
    return;
  }
  resultList.innerHTML = list.map((x, i) =>
    '<div class="tool-card" style="cursor:pointer;" data-idx="' + i + '">' +
    '<div style="display:flex;justify-content:space-between;align-items:start;gap:0.5rem;">' +
    '<div style="flex:1;">' +
    '<div style="font-size:1.05rem;font-weight:600;">' + x.front + ' <span style="color:var(--primary);">—— ' + x.back + '</span></div>' +
    '<div style="margin-top:0.4rem;font-size:0.85rem;opacity:0.8;">' + x.exp + '</div>' +
    '</div>' +
    '<span style="font-size:0.7rem;background:var(--bg-secondary);padding:2px 8px;border-radius:10px;">' + x.cat + '</span>' +
    '</div>' +
    '</div>'
  ).join('');
  resultList.querySelectorAll('.tool-card').forEach(card => {
    card.addEventListener('click', () => {
      const idx = parseInt(card.dataset.idx);
      const item = list[idx];
      copyToClipboard(item.front + ' —— ' + item.back);
    });
  });
}

function randomOne() {
  const list = getFiltered();
  if (!list.length) return;
  const item = list[Math.floor(Math.random() * list.length)];
  resultList.innerHTML = '<div class="tool-card" style="border:2px solid var(--primary);">' +
    '<div style="font-size:1.2rem;font-weight:600;">🎲 ' + item.front + '</div>' +
    '<div style="margin-top:0.5rem;color:var(--primary);font-size:1.1rem;font-weight:600;">—— ' + item.back + '</div>' +
    '<div style="margin-top:0.5rem;font-size:0.85rem;opacity:0.8;">' + item.exp + '</div>' +
    '<div style="margin-top:0.5rem;font-size:0.75rem;opacity:0.6;">分类：' + item.cat + ' · 点击复制</div>' +
    '</div>';
  copyToClipboard(item.front + ' —— ' + item.back);
}

