function pad(n) { return n < 10 ? '0' + n : '' + n; }
function fmtDate(d) {
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}
function fmtDay(d) {
  const w = ['日','一','二','三','四','五','六'];
  return d.getFullYear() + '年' + (d.getMonth()+1) + '月' + d.getDate() + '日 (周' + w[d.getDay()] + ')';
}
function addDays(d, n) { const r = new Date(d); r.setDate(r.getDate() + n); return r; }
function addMonths(d, n) { const r = new Date(d); r.setMonth(r.getMonth() + n); return r; }

function calc() {
  const v = birthInput.value;
  if (!v) { output.innerHTML = '<div style="opacity:0.6;padding:1rem;text-align:center;">请选择出生日期</div>'; return; }
  const birth = new Date(v);
  if (isNaN(birth)) return;

  const events = [
    { name: '🍃 满月',        date: addMonths(birth, 1) },
    { name: '🎉 百日宴',      date: addDays(birth, 100) },
    { name: '🎂 半岁',        date: addMonths(birth, 6) },
    { name: '🎈 抓周',        date: addDays(birth, 365) },
    { name: '🎊 两岁',        date: addDays(birth, 365 * 2) },
    { name: '🧒 幼儿园',     date: addDays(birth, 365 * 3) },
    { name: '🎓 学龄',        date: addDays(birth, 365 * 6) },
    { name: '🌟 十二岁',      date: addDays(birth, 365 * 12) },
    { name: '🏫 中考',        date: addDays(birth, 365 * 15) },
    { name: '🎓 高考',        date: addDays(birth, 365 * 18) },
  ];

  const now = new Date();
  const items = events.map(e => {
    const diff = Math.round((e.date - now) / 86400000);
    let badge;
    if (diff > 0) badge = '<span style="background:#3b82f6;color:#fff;padding:0.15rem 0.55rem;border-radius:12px;font-size:0.75rem;">还有 ' + diff + ' 天</span>';
    else if (diff === 0) badge = '<span style="background:#22c55e;color:#fff;padding:0.15rem 0.55rem;border-radius:12px;font-size:0.75rem;">就是今天！</span>';
    else badge = '<span style="background:#94a3b8;color:#fff;padding:0.15rem 0.55rem;border-radius:12px;font-size:0.75rem;">已过 ' + Math.abs(diff) + ' 天</span>';
    return '<div style="display:flex;justify-content:space-between;align-items:center;padding:0.7rem 0.6rem;border-bottom:1px solid var(--border);">'
      + '<div>'
      +   '<div style="font-weight:600;font-size:0.95rem;">' + e.name + '</div>'
      +   '<div style="font-size:0.82rem;opacity:0.7;font-family:monospace;">' + fmtDay(e.date) + '</div>'
      + '</div>'
      + badge
      + '</div>';
  }).join('');

  output.innerHTML = '<div style="background:var(--bg-secondary);padding:0.75rem 1rem;border-radius:10px;margin-bottom:0.75rem;font-size:0.9rem;line-height:1.7;">'
    + '🎂 出生日期：<b>' + fmtDay(birth) + '</b><br>'
    + '⏰ 当前时间：<b>' + fmtDate(now) + '</b>'
    + '</div>'
    + items;
}

