// 每种血型可能携带的等位基因组合
const GENOTYPE_POOL = {
  'A':  [['IA','IA'], ['IA','i']],
  'B':  [['IB','IB'], ['IB','i']],
  'AB': [['IA','IB']],
  'O':  [['i','i']],
};

const fatherSel = document.getElementById('fatherType');
const motherSel = document.getElementById('motherType');
['A','B','AB','O'].forEach(t => {
  const o1 = document.createElement('option'); o1.value = t; o1.textContent = t + ' 型';
  const o2 = document.createElement('option'); o2.value = t; o2.textContent = t + ' 型';
  fatherSel.appendChild(o1); motherSel.appendChild(o2);
});
fatherSel.value = 'A'; motherSel.value = 'B';

function cross(father, mother) {
  const counts = { A: 0, B: 0, AB: 0, O: 0 };
  let total = 0;
  for (const fg of GENOTYPE_POOL[father]) {
    for (const mg of GENOTYPE_POOL[mother]) {
      for (let fi = 0; fi < 2; fi++) {
        for (let mi = 0; mi < 2; mi++) {
          const a1 = fg[fi], a2 = mg[mi];
          let childType;
          if ((a1 === 'IA' && a2 === 'IB') || (a1 === 'IB' && a2 === 'IA')) childType = 'AB';
          else if (a1 === 'IA' || a2 === 'IA') childType = 'A';
          else if (a1 === 'IB' || a2 === 'IB') childType = 'B';
          else childType = 'O';
          counts[childType]++;
          total++;
        }
      }
    }
  }
  return { counts, total };
}

function calc() {
  const f = fatherSel.value, m = motherSel.value;
  const { counts, total } = cross(f, m);
  const output = document.getElementById('output');
  const order = ['A','B','AB','O'];
  const colors = { A: '#3b82f6', B: '#ef4444', AB: '#a855f7', O: '#22c55e' };
  const items = order.map(t => {
    const pct = ((counts[t] / total) * 100);
    const exists = counts[t] > 0;
    return '<div style="display:flex;align-items:center;gap:0.75rem;padding:0.6rem 0.5rem;border-bottom:1px solid var(--border);' + (exists ? '' : 'opacity:0.35;') + '">'
      + '<div style="width:60px;font-weight:600;color:' + colors[t] + ';">' + t + ' 型</div>'
      + '<div style="flex:1;height:10px;background:var(--bg-secondary);border-radius:5px;overflow:hidden;">'
      +   '<div style="width:' + pct + '%;height:100%;background:' + colors[t] + ';"></div>'
      + '</div>'
      + '<div style="min-width:60px;text-align:right;font-family:monospace;">' + pct.toFixed(1) + '%</div>'
      + '</div>';
  }).join('');
  const possible = order.filter(t => counts[t] > 0).map(t => '<b style="color:' + colors[t] + ';">' + t + '</b>').join(' / ');
  output.innerHTML = '<div style="background:var(--bg-secondary);padding:0.75rem 1rem;border-radius:10px;margin-bottom:0.75rem;line-height:1.6;">'
    + '父亲 <b>' + f + '</b> 型 × 母亲 <b>' + m + '</b> 型 → 子女可能血型：' + (possible || '无')
    + '</div>'
    + items;
}

document.getElementById('copyOutput').onclick = () => copyToClipboard(document.getElementById('output').innerText);
fatherSel.addEventListener('change', calc);
motherSel.addEventListener('change', calc);
calc();

const fatherInput = document.getElementById('fatherHeight');
const motherInput = document.getElementById('motherHeight');
const genderSel = document.getElementById('childGender');
const ageInput = document.getElementById('childAge');
const output = document.getElementById('output');

const BOY_AGE_H = { 0:50, 1:75, 2:87, 3:96, 4:103, 5:109, 6:115, 7:121, 8:127, 9:132, 10:137, 11:143, 12:149, 13:156, 14:163, 15:168, 16:171, 17:173 };
const GIRL_AGE_H = { 0:49, 1:74, 2:86, 3:95, 4:102, 5:108, 6:114, 7:120, 8:126, 9:132, 10:138, 11:144, 12:151, 13:156, 14:159, 15:161, 16:162 };

function calc() {
  const f = parseFloat(fatherInput.value);
  const m = parseFloat(motherInput.value);
  if (!f || !m || f < 100 || m < 100) { output.innerHTML = '<div style="padding:1rem;text-align:center;opacity:0.6;">请输入有效的父母身高（≥100cm）</div>'; return; }
  const gender = genderSel.value;
  // CMH公式：男孩 = (父+母+13)/2；女孩 = (父+母-13)/2；±7.5cm
  const target = gender === 'boy' ? (f + m + 13) / 2 : (f + m - 13) / 2;
  const min = target - 7.5;
  const max = target + 7.5;
  const age = parseFloat(ageInput.value);

  let html = '';
  html += '<div style="background:var(--bg-secondary);padding:1rem;border-radius:12px;margin-bottom:0.75rem;">'
    + '<div style="font-size:0.85rem;opacity:0.65;margin-bottom:0.4rem;">' + (gender === 'boy' ? '👦 男孩' : '👧 女孩') + ' 遗传靶身高</div>'
    + '<div style="font-size:2.2rem;font-weight:700;color:var(--primary);text-align:center;font-family:monospace;">' + target.toFixed(1) + ' <span style="font-size:1rem;opacity:0.6;">cm</span></div>'
    + '</div>';
  html += '<div style="background:var(--bg-secondary);padding:1rem;border-radius:12px;margin-bottom:0.75rem;">'
    + '<div style="font-size:0.85rem;opacity:0.65;margin-bottom:0.5rem;">预测范围（±7.5cm）</div>'
    + '<div style="display:flex;align-items:center;gap:0.5rem;">'
    +   '<div style="font-family:monospace;font-size:1.1rem;font-weight:600;">' + min.toFixed(1) + ' cm</div>'
    +   '<div style="flex:1;height:8px;background:linear-gradient(90deg, #f59e0b, #22c55e, #f59e0b);border-radius:4px;"></div>'
    +   '<div style="font-family:monospace;font-size:1.1rem;font-weight:600;">' + max.toFixed(1) + ' cm</div>'
    + '</div>'
    + '</div>';
  if (age && age > 0) {
    const tbl = gender === 'boy' ? BOY_AGE_H : GIRL_AGE_H;
    const k = Math.min(17, Math.max(0, Math.floor(age)));
    const refH = tbl[k] ? tbl[k] + 'cm' : '超出参考范围';
    html += '<div style="background:var(--bg-secondary);padding:0.75rem 1rem;border-radius:10px;font-size:0.85rem;line-height:1.7;">'
      + '📏 <b>' + age + '岁' + (gender === 'boy' ? '男孩' : '女孩') + '</b> 当前身高参考：<b>' + refH + '</b>'
      + '</div>';
  }
  let noteHtml = '<div style="margin-top:0.75rem;padding:0.6rem 0.8rem;background:var(--bg-secondary);border-radius:8px;font-size:0.78rem;opacity:0.75;line-height:1.7;">'
    + '📐 采用 <b>CMH公式</b>（中国儿童身高预测标准）。实际身高受营养、运动、睡眠等因素影响，遗传因素约占 70%。';
  if (age && age > 0) {
    const remaining = Math.max(0, (gender === 'boy' ? 17 : 16) - age);
    noteHtml += '<br>⏳ 距离身高基本定型还有约 <b>' + remaining.toFixed(1) + '</b> 年。';
  }
  noteHtml += '</div>';
  output.innerHTML = html + noteHtml;
}

document.getElementById('calcBtn').onclick = calc;
[fatherInput, motherInput, ageInput].forEach(el => el.addEventListener('input', calc));
genderSel.addEventListener('change', calc);
document.getElementById('copyOutput').onclick = () => copyToClipboard(output.innerText);
