const SHENGMU = [
  ['b', '玻'], ['p', '坡'], ['m', '摸'], ['f', '佛'],
  ['d', '得'], ['t', '特'], ['n', '讷'], ['l', '勒'],
  ['g', '哥'], ['k', '科'], ['h', '喝'],
  ['j', '基'], ['q', '欺'], ['x', '希'],
