let currentSoup = '';
let history = [];

function pick() {
  const cat = document.querySelector('input[name="cat"]:checked').value;
  const pool = cat === 'all' ? SOUPS : SOUPS.filter(s => s.cat === cat);
  let next;
  do { next = pool[Math.floor(Math.random() * pool.length)]; } while (next === currentSoup && pool.length > 1);
  return next;
}

function render() {
  const soup = pick();
  if (!soup) {
    document.getElementById('soup').textContent = '该分类暂无内容';
    return;
  }
  currentSoup = soup;
  document.getElementById('soup').innerHTML = soup.text + '<br><span style="font-size:0.8rem;opacity:0.6;display:block;margin-top:0.75rem;">[' + soup.cat + ']</span>';
  if (history[0] !== soup.text) {
    history.unshift(soup.text);
    if (history.length > 30) history = history.slice(0, 30);
    renderHistory();
  }
}

function renderHistory() {
  const el = document.getElementById('history');
  if (!history.length) {
    el.innerHTML = '<div style="text-align:center;opacity:0.5;padding:1rem;font-size:0.85rem;">暂无记录</div>';
    return;
  }
  el.innerHTML = history.map((h, i) =>
    '<div style="padding:0.5rem;border-bottom:1px solid var(--border);font-size:0.9rem;display:flex;justify-content:space-between;gap:0.5rem;align-items:start;">' +
    '<span style="flex:1;">' + (i + 1) + '. ' + h + '</span>' +
    '<button class="btn btn-secondary" data-copy="' + i + '" style="font-size:0.75rem;padding:0.2rem 0.5rem;">复制</button>' +
    '</div>'
  ).join('');
  el.querySelectorAll('[data-copy]').forEach(btn => {
    btn.addEventListener('click', () => {
      copyToClipboard(history[parseInt(btn.dataset.copy)]);
    });
  });
}

