// Temperature conversions
function tempToBase(v, k) {
  if (k === 'C') return v + 273.15;
  if (k === 'F') return (v - 32) * 5/9 + 273.15;
  if (k === 'K') return v;
  if (k === 'R') return v * 5/9;
  return v;
}
function fromBase(v, k) {
  if (k === 'C') return v - 273.15;
  if (k === 'F') return (v - 273.15) * 9/5 + 32;
  if (k === 'K') return v;
  if (k === 'R') return v * 9/5;
  return v;
}

const catSel = document.getElementById('category');
const fromSel = document.getElementById('fromUnit');
const toSel = document.getElementById('toUnit');
const inputVal = document.getElementById('inputVal');
const output = document.getElementById('output');

function populateUnits() {
  const cat = CATEGORIES[catSel.value];
  fromSel.innerHTML = '';
  toSel.innerHTML = '';
  cat.units.forEach((u, i) => {
    const o1 = document.createElement('option'); o1.value = u.key; o1.textContent = u.name;
    const o2 = o1.cloneNode(true);
    fromSel.appendChild(o1);
    toSel.appendChild(o2);
  });
  fromSel.value = cat.units[0].key;
  toSel.value = cat.units[Math.min(3, cat.units.length-1)].key;
}

function fmt(v) {
  if (!isFinite(v)) return '∞';
  if (v === 0) return '0';
  const abs = Math.abs(v);
  if (abs >= 1e15 || abs < 1e-6) return v.toExponential(6);
  if (abs >= 1e6) return v.toLocaleString('en-US', { maximumFractionDigits: 4 });
  return v.toLocaleString('en-US', { maximumFractionDigits: 8 });
}

function convert() {
  try {
    const cat = CATEGORIES[catSel.value];
    const v = parseFloat(inputVal.value);
    if (isNaN(v)) {
      output.innerHTML = '<div style="padding:1rem;text-align:center;opacity:0.6;">请输入有效数值</div>';
      return;
    }
    const fromU = cat.units.find(u => u.key === fromSel.value);
    const toU = cat.units.find(u => u.key === toSel.value);
    let result;
    if (cat.special) {
      const base = tempToBase(v, fromU.key);
      result = fromBase(base, toU.key);
    } else {
      const baseVal = v * fromU.factor;
      result = baseVal / toU.factor;
    }
    const html = ''
      + '<div style="background:var(--bg-secondary);padding:1.2rem;border-radius:12px;text-align:center;margin-bottom:0.75rem;">'
      + '<div style="font-size:0.85rem;opacity:0.7;margin-bottom:0.5rem;">'
      +   '<span style="font-family:monospace;">' + v + '</span> '
      +   '<span style="opacity:0.85;">' + fromU.name + '</span>'
      +   ' <span style="opacity:0.5;">=</span>'
      + '</div>'
      + '<div style="font-size:1.8rem;font-weight:700;color:var(--primary);font-family:monospace;word-break:break-all;">' + fmt(result) + '</div>'
      + '<div style="font-size:0.95rem;opacity:0.85;margin-top:0.4rem;">' + toU.name + '</div>'
      + '</div>'
      + '<div style="font-size:0.78rem;opacity:0.65;text-align:center;">'
      + '📐 类别：' + cat.name + ' | 基准单位：' + cat.base + (cat.special ? ' (含非比例换算)' : ' (线性换算)')
      + '</div>';
    output.innerHTML = html;
  } catch (e) {
    output.innerHTML = '<div style="padding:1rem;text-align:center;color:#ef4444;">❌ 换算失败：' + e.message + '</div>';
  }
}

catSel.addEventListener('change', () => { populateUnits(); convert(); });
fromSel.addEventListener('change', convert);
toSel.addEventListener('change', convert);
inputVal.addEventListener('input', convert);
document.getElementById('swapBtn').onclick = () => {
  const tmp = fromSel.value; fromSel.value = toSel.value; toSel.value = tmp;
  convert();
};
document.getElementById('copyOutput').onclick = () => {
  const v = parseFloat(inputVal.value);
  if (isNaN(v)) return;
  const cat = CATEGORIES[catSel.value];
  const fromU = cat.units.find(u => u.key === fromSel.value);
  const toU = cat.units.find(u => u.key === toSel.value);
  let result;
  if (cat.special) { const base = tempToBase(v, fromU.key); result = fromBase(base, toU.key); }
  else { const baseVal = v * fromU.factor; result = baseVal / toU.factor; }
  copyToClipboard(v + ' ' + fromU.name + ' = ' + fmt(result) + ' ' + toU.name);
};

populateUnits();
convert();

