const ZODIAC_NUM = {
  '鼠':2,'牛':1,'虎':7,'兔':9,
  '龙':5,'蛇':0,'马':8,'羊':6,
  '猴':3,'鸡':4,'狗':1,'猪':6
};

function hashCode(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h);
}

function pad(n) { return n < 10 ? '0' + n : '' + n; }

function dayElement(dateStr, zodiac) {
  // Base on date seed
  const d = new Date(dateStr);
  const seed = d.getFullYear() * 10000 + (d.getMonth()+1) * 100 + d.getDate();
  const h = hashCode(seed + 'day');
  const order = ['金','木','水','火','土'];
  return order[h % 5];
}

function pickPalette(dateStr, ele) {
  const d = new Date(dateStr);
  const seed = d.getFullYear() * 10000 + (d.getMonth()+1) * 100 + d.getDate();
  const h = hashCode(seed + 'color');
  const arr = PALETTES[ele];
  return arr[h % arr.length];
}

function pickNumber(dateStr, zodiac) {
  const d = new Date(dateStr);
  const seed = d.getFullYear() * 10000 + (d.getMonth()+1) * 100 + d.getDate();
  const h = hashCode(seed + 'num');
  const base = (h % 9) + 1;
  if (zodiac && ZODIAC_NUM[zodiac] !== undefined) {
    return [base, ZODIAC_NUM[zodiac], (base + ZODIAC_NUM[zodiac]) % 10 || 10];
  }
  return [base, ((base + 3) % 9) + 1, ((base * 2) % 9) + 1];
}

function pickOutfit(ele, palette) {
