    金: { main: '白色或金色上衣', accent: '深色下装 (黑/深灰)',  avoid: '避开过于鲜艳的红绿撞色' },
    木: { main: '绿色或米色系',   accent: '浅蓝/白色单品',        avoid: '避免全黑压抑搭配' },
    水: { main: '蓝色或黑色上衣', accent: '白色/银色配饰',        avoid: '避免过多暖橙黄' },
    火: { main: '红色或橙色单品', accent: '米白/黑色平衡',        avoid: '避免一身素白冷感' },
    土: { main: '棕色/赭色系',    accent: '金黄/米色层次',        avoid: '避免冷色调过于集中' },
  };
  return tips[ele];
}

function luminance(hex) {
  const r = parseInt(hex.slice(1,3), 16);
  const g = parseInt(hex.slice(3,5), 16);
  const b = parseInt(hex.slice(5,7), 16);
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255;
}

function contrastText(hex) {
  return luminance(hex) > 0.6 ? '#1a1a1a' : '#ffffff';
}

