let chartInstance = null;

function parseData() {
  const raw = document.getElementById('dataInput').value.trim();
  if (!raw) return { labels: [], values: [] };
  const lines = raw.split(/\r?\n/).filter(l => l.trim());
  const labels = [];
  const values = [];
  for (const line of lines) {
    const parts = line.split(/[,，\t]/);
    if (parts.length >= 2) {
      const label = parts[0].trim();
      const val = parseFloat(parts[1].trim());
      if (!isNaN(val)) {
        labels.push(label);
        values.push(val);
      }
    }
  }
  return { labels, values };
}

function renderChart() {
  const { labels, values } = parseData();
  if (!labels.length) {
    CT && CT.showToast ? CT.showToast('请输入有效数据') : alert('请输入有效数据');
    return;
  }
  const title = document.getElementById('chartTitle').value || '柱状图';
  const xLabel = document.getElementById('xLabel').value || '';
  const yLabel = document.getElementById('yLabel').value || '';
  const color = document.getElementById('barColor').value || '#4f46e5';
  const legendPos = document.getElementById('legendPos').value;
  const orientation = document.getElementById('orientation').value;

  const ctx = document.getElementById('chartCanvas').getContext('2d');
  if (chartInstance) chartInstance.destroy();

  const baseColor = color;
  const bgColors = values.map(v => v < 0 ? 'rgba(239,68,68,0.7)' : hexToRgba(baseColor, 0.75));
  const borderColors = values.map(v => v < 0 ? 'rgba(239,68,68,1)' : baseColor);

  chartInstance = new Chart(ctx, {
    type: 'bar',
    data: {
      labels,
      datasets: [{
        label: title,
        data: values,
        backgroundColor: bgColors,
        borderColor: borderColors,
        borderWidth: 2,
        borderRadius: 4,
      }],
    },
    options: {
      indexAxis: orientation === 'h' ? 'y' : 'x',
      responsive: true,
      maintainAspectRatio: true,
      plugins: {
        title: {
          display: true,
          text: title,
          font: { size: 18, weight: 'bold' },
          padding: { top: 8, bottom: 16 },
        },
        legend: {
          display: legendPos !== 'none',
          position: legendPos === 'none' ? 'top' : legendPos,
        },
        tooltip: {
          callbacks: {
            label: ctx => `${ctx.dataset.label || ''}: ${ctx.parsed[orientation === 'h' ? 'x' : 'y']}`,
          },
        },
      },
      scales: {
        x: {
          title: { display: !!xLabel, text: xLabel },
          beginAtZero: true,
        },
        y: {
          title: { display: !!yLabel, text: yLabel },
          beginAtZero: true,
        },
      },
    },
  });
}

function hexToRgba(hex, alpha) {
  const m = hex.replace('#', '').match(/.{2}/g);
  if (!m) return hex;
  const [r, g, b] = m.map(h => parseInt(h, 16));
  return `rgba(${r},${g},${b},${alpha})`;
}

