let chartInstance = null;
const palette = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

function parseData() {
  const raw = document.getElementById('dataInput').value.trim();
  if (!raw) return { labels: [], series: [] };
  const lines = raw.split(/\r?\n/).filter(l => l.trim());
  const labels = [];
  const series = []; // [[v1,v2,v3], [v1,v2,v3]]
  for (const line of lines) {
    const parts = line.split(/[,，\t]/);
    if (parts.length >= 2) {
      labels.push(parts[0].trim());
      const nums = [];
      for (let i = 1; i < parts.length; i++) {
        const v = parseFloat(parts[i].trim());
        nums.push(isNaN(v) ? null : v);
      }
      series.push(nums);
    }
  }
  // Determine max series count
  const seriesCount = Math.max(...series.map(s => s.length), 1);
  // Transpose: [{name, data:[v,v,v]}, ...]
  const transposed = [];
  for (let i = 0; i < seriesCount; i++) {
    transposed.push({
      data: series.map(row => row[i] ?? null),
    });
  }
  return { labels, transposed };
}

function hexToRgba(hex, alpha) {
  const m = hex.replace('#', '').match(/.{2}/g);
  if (!m) return hex;
  const [r, g, b] = m.map(h => parseInt(h, 16));
  return `rgba(${r},${g},${b},${alpha})`;
}

function renderChart() {
  const { labels, transposed } = parseData();
  if (!labels.length || !transposed.length) {
    if (CT && CT.showToast) CT.showToast('请输入有效数据');
    else alert('请输入有效数据');
    return;
  }
  const title = document.getElementById('chartTitle').value || '折线图';
  const xLabel = document.getElementById('xLabel').value || '';
  const yLabel = document.getElementById('yLabel').value || '';
  const seriesNames = document.getElementById('seriesNames').value
    .split(/[,，]/).map(s => s.trim()).filter(Boolean);
  const colors = [
    document.getElementById('color1').value,
    document.getElementById('color2').value,
    document.getElementById('color3').value,
  ];
  const pointStyle = document.getElementById('pointStyle').value;
  const tension = parseFloat(document.getElementById('tension').value);
  const fillMode = document.getElementById('fill').value;

  const datasets = transposed.map((s, i) => {
    const color = colors[i] || palette[i % palette.length];
    return {
      label: seriesNames[i] || `系列${i + 1}`,
      data: s.data,
      borderColor: color,
      backgroundColor: fillMode !== 'false' ? hexToRgba(color, 0.15) : color,
      borderWidth: 2.5,
      tension,
      fill: fillMode !== 'false',
      pointRadius: pointStyle === 'false' ? 0 : 5,
      pointHoverRadius: pointStyle === 'false' ? 0 : 7,
      pointStyle: pointStyle === 'false' ? 'circle' : pointStyle,
      pointBackgroundColor: color,
      spanGaps: true,
    };
  });

  const ctx = document.getElementById('chartCanvas').getContext('2d');
  if (chartInstance) chartInstance.destroy();
  chartInstance = new Chart(ctx, {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: true,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        title: {
          display: true,
          text: title,
          font: { size: 18, weight: 'bold' },
          padding: { top: 8, bottom: 16 },
        },
        legend: { position: 'top' },
      },
      scales: {
        x: {
          title: { display: !!xLabel, text: xLabel },
        },
        y: {
          title: { display: !!yLabel, text: yLabel },
          beginAtZero: false,
        },
      },
    },
  });
}

function downloadPNG() {
  if (!chartInstance) renderChart();
  const canvas = document.getElementById('chartCanvas');
  const url = canvas.toDataURL('image/png');
  const a = document.createElement('a');
  a.href = url;
  a.download = (document.getElementById('chartTitle').value || 'line-chart') + '.png';
