      <button class="btn-icon" data-action="up" title="上移" style="background:none;border:1px solid var(--border);border-radius:4px;padding:.2rem .5rem;cursor:pointer;">↑</button>
      <button class="btn-icon" data-action="down" title="下移" style="background:none;border:1px solid var(--border);border-radius:4px;padding:.2rem .5rem;cursor:pointer;">↓</button>
      <button class="btn-icon" data-action="remove" title="移除" style="background:none;border:1px solid var(--border);border-radius:4px;padding:.2rem .5rem;cursor:pointer;color:#ef4444;">✕</button>
    </li>
  `).join('');
}

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[c]);
}

function addFiles(list) {
  const added = [];
  for (const f of list) {
    if (f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf')) {
      added.push({ id: Math.random().toString(36).slice(2), file: f, name: f.name, size: f.size });
    }
  }
  files = files.concat(added);
  renderList();
  if (added.length) {
    statusEl.textContent = `已添加 ${added.length} 个文件（总计 ${files.length} 个）`;
  }
}

function clearAll() {
  files = [];
  renderList();
  statusEl.textContent = '';
}

fileInput.addEventListener('change', e => {
  addFiles(Array.from(e.target.files));
  fileInput.value = '';
});

['dragenter', 'dragover'].forEach(ev =>
  dropZone.addEventListener(ev, e => { e.preventDefault(); dropZone.style.background = 'var(--bg-primary)'; dropZone.style.borderColor = 'var(--primary)'; })
);
['dragleave', 'drop'].forEach(ev =>
  dropZone.addEventListener(ev, e => { e.preventDefault(); dropZone.style.background = ''; dropZone.style.borderColor = ''; })
);
dropZone.addEventListener('drop', e => {
  const dt = e.dataTransfer;
  if (dt && dt.files && dt.files.length) addFiles(Array.from(dt.files));
});

fileList.addEventListener('click', e => {
  const btn = e.target.closest('button[data-action]');
  if (!btn) return;
  const li = btn.closest('li[data-id]');
  const id = li.dataset.id;
  const idx = files.findIndex(f => f.id === id);
  if (idx < 0) return;
  const action = btn.dataset.action;
  if (action === 'up' && idx > 0) {
    [files[idx - 1], files[idx]] = [files[idx], files[idx - 1]];
  } else if (action === 'down' && idx < files.length - 1) {
    [files[idx + 1], files[idx]] = [files[idx], files[idx + 1]];
  } else if (action === 'remove') {
    files.splice(idx, 1);
  }
  renderList();
});

clearBtn.addEventListener('click', clearAll);

async function mergePDFs() {
  if (!files.length) return;
  if (typeof PDFLib === 'undefined') {
    statusEl.textContent = '错误：PDFLib 未加载，请检查网络';
    return;
  }
  statusEl.textContent = '合并中...';
  mergeBtn.disabled = true;
  try {
    const merged = await PDFLib.PDFDocument.create();
    for (let i = 0; i < files.length; i++) {
      const bytes = await files[i].file.arrayBuffer();
      const src = await PDFLib.PDFDocument.load(bytes, { ignoreEncryption: true });
      const pages = await merged.copyPages(src, src.getPageIndices());
      pages.forEach(p => merged.addPage(p));
      statusEl.textContent = `合并中... ${i + 1}/${files.length}`;
    }
    const out = await merged.save();
    const blob = new Blob([out], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `merged_${Date.now()}.pdf`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 5000);
    statusEl.textContent = `✅ 合并完成！共 ${files.length} 个文件，输出 ${(out.length / 1024).toFixed(1)} KB`;
    if (CT && CT.showToast) CT.showToast('合并完成，已下载');
  } catch (err) {
    statusEl.textContent = '❌ 合并失败：' + (err.message || err);
    console.error(err);
  } finally {
    mergeBtn.disabled = false;
  }
}

mergeBtn.addEventListener('click', mergePDFs);

