          <option value="270" ${deg === 270 ? 'selected' : ''}>270°</option>
        </select>
      </div>
    `;
  }).join('');
}

async function loadFile(file) {
  if (!file) return;
  if (!file.name.toLowerCase().endsWith('.pdf') && file.type !== 'application/pdf') {
    statusEl.textContent = '请选择 PDF 文件';
    return;
  }
  if (typeof PDFLib === 'undefined') {
    statusEl.textContent = '错误：PDFLib 未加载';
    return;
  }
  statusEl.textContent = '加载中...';
  try {
    pdfBytes = await file.arrayBuffer();
    pdfDoc = await PDFLib.PDFDocument.load(pdfBytes, { ignoreEncryption: true });
    rotations = new Array(pdfDoc.getPageCount()).fill(0);
    meta.style.display = '';
    meta.textContent = `文件：${escapeHtml(file.name)} · 大小：${fmtSize(file.size)} · 共 ${pdfDoc.getPageCount()} 页`;
    pageSettings.style.display = '';
    renderPageGrid();
    applyBtn.disabled = false;
    resetBtn.disabled = false;
    statusEl.textContent = `已加载 ${pdfDoc.getPageCount()} 页`;
  } catch (err) {
    statusEl.textContent = '加载失败：' + (err.message || err);
    console.error(err);
  }
}

