async function applyRotation() {
  if (!pdfDoc) return;
  statusEl.textContent = '处理中...';
  applyBtn.disabled = true;
  try {
    const out = await PDFLib.PDFDocument.create();
    const pages = await out.copyPages(pdfDoc, pdfDoc.getPageIndices());
    pages.forEach((p, i) => {
      const current = p.getRotation().angle || 0;
      const total = (current + (rotations[i] || 0)) % 360;
      p.setRotation(PDFLib.degrees(total));
      out.addPage(p);
    });
    const bytes = await out.save();
    const blob = new Blob([bytes], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `rotated_${Date.now()}.pdf`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 5000);
    statusEl.textContent = `✅ 完成！输出 ${(bytes.length / 1024).toFixed(1)} KB`;
    if (CT && CT.showToast) CT.showToast('已下载旋转后的 PDF');
  } catch (err) {
    statusEl.textContent = '❌ 失败：' + (err.message || err);
    console.error(err);
  } finally {
    applyBtn.disabled = false;
  }
}

applyBtn.addEventListener('click', applyRotation);

