function drawWatermarks(ctx, w, h) {
  const wmType = document.querySelector('input[name="wmType"]:checked').value;
  const layout = $('wmLayout').value;
  const margin = parseInt($('wmMargin').value, 10) || 0;

  if (wmType === 'image') {
    if (!watermarkImage) return;
    const scale = parseFloat($('wmImgScale').value) || 0.25;
    const opacity = parseFloat($('wmImgOpacity').value) || 0.7;
    drawImageWatermark(ctx, w, h, layout, scale, opacity, margin);
  } else {
    const text = $('wmText').value || '';
    if (!text) return;
    const fontSize = parseInt($('wmFontSize').value, 10) || 36;
    const color = $('wmColor').value || '#ffffff';
    const opacity = parseFloat($('wmOpacity').value) || 0.6;
    const shadow = $('wmShadow').value;
    const rotate = parseInt($('wmRotate').value, 10) || 0;
    drawTextWatermark(ctx, w, h, layout, text, fontSize, color, opacity, shadow, rotate, margin);
  }
}

function drawTextWatermark(ctx, W, H, layout, text, fontSize, color, opacity, shadow, rotate, margin) {
  ctx.save();
  ctx.font = `bold ${fontSize}px sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.globalAlpha = opacity;

  if (shadow === 'light') {
    ctx.shadowColor = 'rgba(0,0,0,0.35)';
    ctx.shadowBlur = 4;
    ctx.shadowOffsetX = 1;
    ctx.shadowOffsetY = 1;
  } else if (shadow === 'strong') {
    ctx.shadowColor = 'rgba(0,0,0,0.7)';
    ctx.shadowBlur = 8;
    ctx.shadowOffsetX = 2;
    ctx.shadowOffsetY = 2;
  }

  const positions = layoutPositions(layout, W, H, margin);
  for (const pos of positions) {
    ctx.save();
    ctx.translate(pos.x, pos.y);
    ctx.rotate((rotate * Math.PI) / 180);
    if (shadow === 'stroke') {
      ctx.strokeStyle = 'rgba(0,0,0,0.7)';
      ctx.lineWidth = Math.max(2, fontSize / 12);
      ctx.strokeText(text, 0, 0);
    }
    ctx.fillStyle = color;
    ctx.fillText(text, 0, 0);
    ctx.restore();
  }
  ctx.restore();
}

function drawImageWatermark(ctx, W, H, layout, scale, opacity, margin) {
  ctx.save();
  ctx.globalAlpha = opacity;
  const wmW = watermarkImage.naturalWidth;
  const wmH = watermarkImage.naturalHeight;
  const targetW = W * scale;
  const ratio = wmH / wmW;
  const targetH = targetW * ratio;

  const positions = layoutPositions(layout, W, H, margin);
  for (const pos of positions) {
    ctx.drawImage(watermarkImage, pos.x - targetW / 2, pos.y - targetH / 2, targetW, targetH);
  }
  ctx.restore();
}

function layoutPositions(layout, W, H, margin) {
  if (layout === 'single') {
    return [{ x: W / 2, y: H / 2 }];
  }
  if (layout === 'diagonal') {
    return [
      { x: W * 0.25, y: H * 0.25 },
      { x: W * 0.75, y: H * 0.5 },
      { x: W * 0.5, y: H * 0.8 },
    ];
  }
  // tile: spaced grid
  const positions = [];
  const stepX = Math.max(80, W / 4);
  const stepY = Math.max(80, H / 5);
  for (let y = margin + stepY / 2; y < H - margin; y += stepY) {
    const offset = (Math.floor(y / stepY) % 2) * (stepX / 2);
    for (let x = margin + stepX / 2 + offset; x < W - margin; x += stepX) {
      positions.push({ x, y });
    }
  }
  return positions;
}

function applyWatermark() {
  if (!sourceImage) return;
  const W = sourceImage.naturalWidth;
  const H = sourceImage.naturalHeight;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(sourceImage, 0, 0);
  drawWatermarks(ctx, W, H);

  const format = $('outFormat').value;
  resultExt = format === 'jpeg' ? 'jpg' : format;
  const mime = 'image/' + format;
  const quality = (parseInt($('outQuality').value, 10) || 92) / 100;

  canvas.toBlob(blob => {
    if (!blob) {
      statusEl.textContent = '生成失败';
      return;
    }
    if (resultUrl) URL.revokeObjectURL(resultUrl);
    resultBlob = blob;
    resultUrl = URL.createObjectURL(blob);
    previewWrap.innerHTML = '';
    const img = document.createElement('img');
    img.src = resultUrl;
    img.style.maxWidth = '100%';
    img.style.maxHeight = '60vh';
    img.style.borderRadius = '4px';
    previewWrap.appendChild(img);
    downloadBtn.disabled = false;
    statusEl.textContent = `✅ 已生成 ${(blob.size / 1024).toFixed(1)} KB，可下载`;
  }, mime, quality);
}

applyBtn.addEventListener('click', applyWatermark);

