const uaInput = document.getElementById('uaInput');
const uaResult = document.getElementById('uaResult');

function escHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function detectUA(ua) {
  const data = {
    raw: ua,
    os: '未知',
    osVersion: '',
    browser: '未知',
    browserVersion: '',
    engine: '未知',
    device: '桌面电脑',
    isBot: false,
    isMobile: false,
    isTablet: false
  };

  if (/bot|spider|crawler|slurp|duckduckbot|baiduspider|yandex|sogou|bingpreview|facebookexternalhit|twitterbot|linkedinbot|applebot/i.test(ua)) {
    data.isBot = true;
  }

  if (/iPad|Android(?!.*Mobile)/i.test(ua)) {
    data.isTablet = true;
    data.device = '平板';
  } else if (/Mobile|iPhone|iPod|Android.*Mobile|IEMobile|Opera Mini/i.test(ua)) {
    data.isMobile = true;
    data.device = '手机';
  } else if (data.isBot) {
    data.device = '爬虫/机器人';
  } else {
    data.device = '桌面电脑';
  }

  let m;
  if ((m = ua.match(/Windows NT ([\d.]+)/))) {
    const map = { '10.0': 'Windows 10/11', '6.3': 'Windows 8.1', '6.2': 'Windows 8', '6.1': 'Windows 7', '6.0': 'Windows Vista' };
    data.os = 'Windows';
    data.osVersion = map[m[1]] || ('NT ' + m[1]);
  } else if ((m = ua.match(/Mac OS X ([\d_]+)/))) {
    data.os = 'macOS';
    data.osVersion = m[1].replace(/_/g, '.');
  } else if ((m = ua.match(/iPhone OS ([\d_]+)/)) || (m = ua.match(/CPU OS ([\d_]+) like Mac OS X/))) {
    data.os = 'iOS';
    data.osVersion = m[1].replace(/_/g, '.');
  } else if ((m = ua.match(/Android ([\d.]+)/))) {
    data.os = 'Android';
    data.osVersion = m[1];
  } else if (/Linux/i.test(ua)) {
    data.os = 'Linux';
    data.osVersion = '';
  } else if (/CrOS/i.test(ua)) {
    data.os = 'Chrome OS';
  }

  if ((m = ua.match(/Edg\/([\d.]+)/))) {
    data.browser = 'Microsoft Edge';
    data.browserVersion = m[1];
    data.engine = 'Blink';
  } else if ((m = ua.match(/OPR\/([\d.]+)/)) || (m = ua.match(/Opera\/([\d.]+)/))) {
    data.browser = 'Opera';
    data.browserVersion = m[1];
    data.engine = 'Blink';
  } else if ((m = ua.match(/Chrome\/([\d.]+)/)) && !/Chromium/i.test(ua)) {
    data.browser = 'Google Chrome';
    data.browserVersion = m[1];
    data.engine = 'Blink';
  } else if ((m = ua.match(/Firefox\/([\d.]+)/))) {
    data.browser = 'Mozilla Firefox';
    data.browserVersion = m[1];
    data.engine = 'Gecko';
  } else if ((m = ua.match(/Version\/([\d.]+).*Safari/)) && /Safari/i.test(ua) && !/Chrome/i.test(ua)) {
    data.browser = 'Safari';
    data.browserVersion = m[1];
    data.engine = 'WebKit';
  } else if (/MSIE|Trident/.test(ua)) {
    data.browser = 'Internet Explorer';
    m = ua.match(/(?:MSIE |rv:)([\d.]+)/);
    data.browserVersion = m ? m[1] : '';
    data.engine = 'Trident';
  } else if (/SamsungBrowser\/([\d.]+)/.test(ua)) {
    m = ua.match(/SamsungBrowser\/([\d.]+)/);
    data.browser = 'Samsung Internet';
    data.browserVersion = m[1];
    data.engine = 'Blink';
  } else if (/UCBrowser\/([\d.]+)/.test(ua)) {
    m = ua.match(/UCBrowser\/([\d.]+)/);
    data.browser = 'UC Browser';
    data.browserVersion = m[1];
    data.engine = 'Blink';
  }

  return data;
}

function renderUA(data) {
  const typeBadge = data.isBot
    ? '<span style="background:#ef4444;color:#fff;padding:.2rem .55rem;border-radius:12px;font-size:.75rem;font-weight:600">🤖 爬虫/机器人</span>'
    : '<span style="background:#22c55e;color:#fff;padding:.2rem .55rem;border-radius:12px;font-size:.75rem;font-weight:600">🌐 浏览器</span>';

  const deviceEmoji = data.isBot ? '🤖' : (data.isTablet ? '📱' : (data.isMobile ? '📱' : '🖥️'));

  const rows = [
    ['🖥️ 操作系统', data.os + (data.osVersion ? ' ' + data.osVersion : '')],
    ['🌐 浏览器', data.browser + (data.browserVersion ? ' ' + data.browserVersion : '')],
    ['⚙️ 渲染引擎', data.engine],
    [deviceEmoji + ' 设备类型', data.device],
    ['📏 UA 长度', String(data.raw.length) + ' 字符']
  ];

  let html = '<div style="display:flex;align-items:center;gap:.6rem;margin-bottom:.75rem;flex-wrap:wrap">' + typeBadge;
  html += '<span style="color:var(--text-secondary);font-size:.85rem">' + escHtml(data.os) + (data.osVersion ? ' ' + escHtml(data.osVersion) : '') + ' · ' + escHtml(data.browser) + (data.browserVersion ? ' ' + escHtml(data.browserVersion) : '') + '</span>';
  html += '</div>';

  html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:.5rem">';
  for (const [label, value] of rows) {
    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:.5rem .7rem;background:var(--bg-secondary);border-radius:6px;gap:.5rem"><span style="font-size:.82rem;color:var(--text-secondary)">' + label + '</span><span style="font-size:.88rem;font-weight:600;text-align:right;word-break:break-all">' + escHtml(value) + '</span></div>';
  }
  html += '</div>';

  html += '<div style="margin-top:.75rem;padding:.6rem .8rem;background:var(--bg-secondary);border-radius:6px"><div style="font-size:.78rem;color:var(--text-secondary);margin-bottom:.3rem">📜 原始 UA</div><code style="font-size:.78rem;word-break:break-all;font-family:monospace;line-height:1.5;display:block">' + escHtml(data.raw) + '</code></div>';

  return html;
}

function parse() {
  const ua = uaInput.value.trim();
  if (!ua) {
    uaResult.innerHTML = '<div style="color:var(--text-secondary);text-align:center;padding:2rem 1rem">👆 请输入或粘贴一个 User-Agent 字符串</div>';
    uaResult.dataset.text = '';
    return;
  }
  try {
    const data = detectUA(ua);
    uaResult.innerHTML = renderUA(data);
    uaResult.dataset.text = JSON.stringify(data, null, 2);
  } catch (e) {
    uaResult.innerHTML = '<div style="color:#ef4444;padding:1rem">❌ 解析失败：' + escHtml(e.message) + '</div>';
    uaResult.dataset.text = 'Error: ' + e.message;
  }
}

