const urlInput = document.getElementById('urlInput');
const methodSel = document.getElementById('method');
const httpResult = document.getElementById('httpResult');
const fetchBtn = document.getElementById('fetchBtn');

function escHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function rowHtml(key, value) {
  return '<div style="display:grid;grid-template-columns:minmax(160px,1fr) 2fr;gap:.5rem;padding:.45rem .7rem;background:var(--bg-secondary);border-radius:6px;align-items:start;word-break:break-all"><code style="font-size:.82rem;color:var(--primary);font-weight:600">' + escHtml(key) + '</code><code style="font-size:.82rem;font-family:monospace">' + escHtml(value) + '</code></div>';
}

function sectionHtml(title, emoji) {
  return '<div style="margin:.5rem 0 .4rem;font-size:.95rem;font-weight:700">' + emoji + ' ' + title + '</div>';
}

async function fetchHeaders() {
  let url = urlInput.value.trim();
  if (!url) {
    httpResult.innerHTML = '<div style="color:#ef4444;padding:1rem">⚠️ 请输入 URL</div>';
    httpResult.dataset.text = '';
    return;
  }
  if (!/^https?:\/\//i.test(url)) {
    url = 'https://' + url;
    urlInput.value = url;
  }
  const method = methodSel.value;

  httpResult.innerHTML = '<div style="color:var(--text-secondary);text-align:center;padding:1.5rem">⏳ 正在请求 ' + escHtml(url) + ' ...</div>';
  httpResult.dataset.text = '';
  fetchBtn.disabled = true;
  fetchBtn.textContent = '⏳ 请求中...';

  const startTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  try {
    const resp = await fetch(url, {
      method: method,
      mode: 'cors',
      cache: 'no-store',
      redirect: 'follow'
    });
    const endTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    const duration = Math.round(endTime - startTime);

    const headerObj = {};
    resp.headers.forEach(function (v, k) { headerObj[k] = v; });

    let html = '';
    html += sectionHtml('请求概要', '📊');
    html += rowHtml('URL', url);
    html += rowHtml('方法', method);
    html += rowHtml('状态', resp.status + ' ' + resp.statusText);
    html += rowHtml('耗时', duration + ' ms');
    html += rowHtml('类型', resp.type);
    html += rowHtml('重定向', resp.redirected ? '是 (' + resp.url + ')' : '否');

    let statusColor = '#22c55e';
    if (resp.status >= 300 && resp.status < 400) statusColor = '#3b82f6';
    else if (resp.status >= 400 && resp.status < 500) statusColor = '#f59e0b';
    else if (resp.status >= 500) statusColor = '#ef4444';
    html += '<div style="margin:.6rem 0;padding:.6rem .8rem;background:' + statusColor + '22;border-left:4px solid ' + statusColor + ';border-radius:6px;font-weight:600;color:' + statusColor + '">⬇ ' + resp.status + ' ' + escHtml(resp.statusText) + '</div>';

    html += sectionHtml('响应头（浏览器可见部分）', '📋');
    if (Object.keys(headerObj).length === 0) {
      html += '<div style="color:var(--text-secondary);padding:.5rem;font-size:.85rem">⚠️ 浏览器未暴露任何响应头（可能是 CORS 限制）</div>';
    } else {
      html += '<div style="display:flex;flex-direction:column;gap:.35rem">';
      for (const k in headerObj) {
        html += rowHtml(k, headerObj[k]);
      }
      html += '</div>';
    }

    const secChecks = [
      { key: 'strict-transport-security', label: 'HSTS', good: '启用 HTTPS 强制' },
      { key: 'content-security-policy', label: 'CSP', good: '启用内容安全策略' },
      { key: 'x-frame-options', label: 'X-Frame-Options', good: '防点击劫持' },
      { key: 'x-content-type-options', label: 'X-Content-Type-Options', good: '禁 MIME 嗅探' },
      { key: 'referrer-policy', label: 'Referrer-Policy', good: '控制 referrer' },
      { key: 'permissions-policy', label: 'Permissions-Policy', good: '限制浏览器特性' }
    ];
    html += sectionHtml('安全头审计', '🛡️');
    html += '<div style="display:flex;flex-direction:column;gap:.3rem">';
    let secCount = 0;
    for (const c of secChecks) {
      const present = headerObj[c.key] !== undefined;
      if (present) secCount++;
      html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:.4rem .7rem;background:var(--bg-secondary);border-radius:6px;gap:.5rem">';
      html += '<div style="display:flex;align-items:center;gap:.5rem"><span style="font-size:1rem">' + (present ? '✅' : '⚠️') + '</span><span style="font-size:.85rem;font-weight:600">' + c.label + '</span><span style="font-size:.78rem;color:var(--text-secondary)">' + c.good + '</span></div>';
      html += '<code style="font-size:.78rem;color:var(--text-secondary);max-width:50%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + (present ? escHtml(headerObj[c.key]) : '未设置') + '</code>';
      html += '</div>';
    }
    html += '</div>';
    html += '<div style="margin-top:.5rem;padding:.5rem .75rem;background:' + (secCount >= 4 ? '#22c55e22' : (secCount >= 2 ? '#f59e0b22' : '#ef444422')) + ';border-radius:6px;font-size:.85rem">安全评分：<strong>' + secCount + '/' + secChecks.length + '</strong>（基于浏览器可见头，仅供参考）</div>';

    const corsKeys = Object.keys(headerObj).filter(function (k) { return /^access-control-/i.test(k); });
    if (corsKeys.length) {
      html += sectionHtml('CORS 相关头', '🔐');
      html += '<div style="display:flex;flex-direction:column;gap:.35rem">';
      for (const k of corsKeys) {
        html += rowHtml(k, headerObj[k]);
      }
      html += '</div>';
    }

    const rawText = [
      method + ' ' + url,
      'Status: ' + resp.status + ' ' + resp.statusText,
      'Type: ' + resp.type + ' | Time: ' + duration + 'ms',
      '',
      '--- Response Headers ---',
      Object.keys(headerObj).map(function (k) { return k + ': ' + headerObj[k]; }).join('\n')
    ].join('\n');
    httpResult.dataset.text = rawText;
    httpResult.innerHTML = html;
  } catch (e) {
    let msg = (e && e.message) ? e.message : String(e);
    let hint = '';
    if (/Failed to fetch/i.test(msg) || /NetworkError/i.test(msg)) {
      hint = '<div style="margin-top:.5rem;padding:.6rem .8rem;background:#ef444422;border-radius:6px;font-size:.85rem;color:#ef4444">💡 可能原因：1) 目标服务器未启用 CORS 2) 网络不通 3) 协议被浏览器阻止（mixed content / HTTPS→HTTP）</div>';
    }
    httpResult.innerHTML = '<div style="color:#ef4444;padding:1rem">❌ 请求失败：' + escHtml(msg) + '</div>' + hint;
    httpResult.dataset.text = 'Request failed: ' + msg;
  } finally {
    fetchBtn.disabled = false;
    fetchBtn.textContent = '🚀 发送请求并查看头';
  }
}

fetchBtn.addEventListener('click', fetchHeaders);
urlInput.addEventListener('keydown', function (e) { if (e.key === 'Enter') fetchHeaders(); });
urlInput.addEventListener('input', function () { httpResult.dataset.text = ''; });

document.getElementById('presetEx').addEventListener('click', function () { urlInput.value = 'https://example.com'; fetchHeaders(); });
document.getElementById('presetGh').addEventListener('click', function () { urlInput.value = 'https://github.com'; fetchHeaders(); });
document.getElementById('presetLocal').addEventListener('click', function () { urlInput.value = 'https://httpbin.org/get'; fetchHeaders(); });
document.getElementById('clearUrl').addEventListener('click', function () { urlInput.value = ''; httpResult.innerHTML = ''; httpResult.dataset.text = ''; });

document.getElementById('copyOutput').addEventListener('click', function () {
  const text = httpResult.dataset.text || httpResult.innerText;
  copyToClipboard(text);
});

fetchHeaders();

const domainInput = document.getElementById('domainInput');
const whoisResult = document.getElementById('whoisResult');
const whoisBtn = document.getElementById('whoisBtn');

function escHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function isValidDomain(d) {
  return /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/i.test(d);
}

const RDAP_BOOTSTRAP = [
  { suffix: '.com', url: 'https://rdap.verisign.com/com/v1/domain/' },
  { suffix: '.net', url: 'https://rdap.verisign.com/net/v1/domain/' },
  { suffix: '.org', url: 'https://rdap.publicinterestregistry.org/rdap/org/v1/domain/' },
  { suffix: '.io', url: 'https://rdap.nic.io/domain/' },
  { suffix: '.dev', url: 'https://rdap.nic.google/domain/' },
  { suffix: '.app', url: 'https://rdap.nic.google/domain/' },
  { suffix: '.cloud', url: 'https://rdap.nic.cloud/domain/' }
];

function pickRdap(domain) {
  for (const b of RDAP_BOOTSTRAP) {
    if (domain.toLowerCase().endsWith(b.suffix)) return b.url;
  }
  return null;
}

function rowHtml(k, v) {
  return '<div style="display:grid;grid-template-columns:minmax(140px,1fr) 2fr;gap:.5rem;padding:.45rem .7rem;background:var(--bg-secondary);border-radius:6px;align-items:start;word-break:break-all"><code style="font-size:.82rem;color:var(--primary);font-weight:600">' + escHtml(k) + '</code><code style="font-size:.82rem;font-family:monospace">' + escHtml(v) + '</code></div>';
}

function formatDate(iso) {
  if (!iso) return '';
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return iso;
    return d.toISOString().replace('T', ' ').slice(0, 19) + ' UTC';
  } catch (e) {
    return iso;
  }
}

function arrayToText(arr) {
  if (!arr) return '';
  if (Array.isArray(arr)) return arr.join(', ');
  return String(arr);
}

function renderRdap(domain, data) {
  let html = '<div style="display:flex;align-items:center;gap:.6rem;margin-bottom:.6rem;flex-wrap:wrap"><span style="background:#22c55e;color:#fff;padding:.2rem .6rem;border-radius:12px;font-size:.75rem;font-weight:600">✅ RDAP 查询成功</span><span style="color:var(--text-secondary);font-size:.85rem">' + escHtml(domain) + '</span></div>';

  const status = arrayToText(data.status);
  if (status) html += rowHtml('状态 (Status)', status);

  const ns = data.nameservers ? data.nameservers.map(function (n) { return n.ldhName || n.unicodeName; }).filter(Boolean) : [];
  if (ns.length) html += rowHtml('Name Servers', ns.join('\n'));

  if (Array.isArray(data.events)) {
    for (const ev of data.events) {
      const action = ev.eventAction || '';
      if (/registration|creation|expiration|last update|last changed|transfer/i.test(action)) {
        html += rowHtml(action, formatDate(ev.eventDate));
      }
    }
  }

  if (Array.isArray(data.entities)) {
    for (const ent of data.entities) {
      const roles = (ent.roles || []).join(', ');
      if (/registrar|registrant|administrative|technical|abuse|billing|reseller/i.test(roles)) {
        let name = '';
        if (ent.vcardArray && Array.isArray(ent.vcardArray[1])) {
          for (const f of ent.vcardArray[1]) {
            if (f[0] === 'fn') { name = f[3]; break; }
          }
        }
        if (!name && ent.handle) name = ent.handle;
        if (name) html += rowHtml(roles, name);
        if (ent.handle && name !== ent.handle) html += rowHtml(roles + ' (handle)', ent.handle);
      }
    }
  }

  if (data.secureDNS) {
    const signed = data.secureDNS.delegationSigned;
    html += rowHtml('DNSSEC', signed ? '已签名 (signed)' : '未签名 (unsigned)');
  }

  if (data.port43) html += rowHtml('WHOIS (port43)', data.port43);

  const raw = JSON.stringify(data, null, 2);
  html += '<details style="margin-top:.75rem"><summary style="cursor:pointer;font-size:.85rem;color:var(--primary)">📜 查看原始 RDAP JSON</summary><pre style="margin-top:.5rem;padding:.6rem;background:var(--bg-secondary);border-radius:6px;font-size:.75rem;max-height:300px;overflow:auto;white-space:pre-wrap;word-break:break-all">' + escHtml(raw) + '</pre></details>';

  html += '<div style="margin-top:.6rem;padding:.5rem .75rem;background:var(--bg-secondary);border-radius:6px;font-size:.8rem;color:var(--text-secondary)">ℹ️ 受 CORS 限制，部分字段可能被浏览器隐藏。完整数据建议使用 <a href="https://lookup.icann.org/" target="_blank" rel="noopener" style="color:var(--primary)">ICANN Lookup</a> 查看。</div>';

  return html;
}

function renderError(domain, msg, hint) {
  let html = '<div style="display:flex;align-items:center;gap:.6rem;margin-bottom:.6rem;flex-wrap:wrap"><span style="background:#f59e0b;color:#fff;padding:.2rem .6rem;border-radius:12px;font-size:.75rem;font-weight:600">⚠️ 查询受限</span><span style="color:var(--text-secondary);font-size:.85rem">' + escHtml(domain) + '</span></div>';
  html += '<div style="padding:.7rem .9rem;background:#ef444422;border-left:4px solid #ef4444;border-radius:6px;font-size:.9rem"><strong>原因：</strong>' + escHtml(msg) + '</div>';
  if (hint) html += '<div style="margin-top:.5rem;padding:.6rem .8rem;background:var(--bg-secondary);border-radius:6px;font-size:.85rem">' + hint + '</div>';
  html += '<div style="margin-top:.75rem;display:flex;gap:.5rem;flex-wrap:wrap"><a href="https://www.whois.com/whois/' + encodeURIComponent(domain) + '" target="_blank" rel="noopener" class="btn btn-secondary" style="font-size:.85rem;text-decoration:none;display:inline-block;padding:.4rem .75rem;border-radius:6px">🌐 在 whois.com 查询</a><a href="https://lookup.icann.org/en/lookup?q=' + encodeURIComponent(domain) + '" target="_blank" rel="noopener" class="btn btn-secondary" style="font-size:.85rem;text-decoration:none;display:inline-block;padding:.4rem .75rem;border-radius:6px">🌐 在 ICANN 查询</a><a href="https://rdap.org/domain/' + encodeURIComponent(domain) + '" target="_blank" rel="noopener" class="btn btn-secondary" style="font-size:.85rem;text-decoration:none;display:inline-block;padding:.4rem .75rem;border-radius:6px">🌐 RDAP.org</a></div>';
  return html;
}

async function queryWhois() {
  const raw = domainInput.value.trim().toLowerCase();
  if (!raw) {
    whoisResult.innerHTML = '<div style="color:#ef4444;padding:1rem">⚠️ 请输入域名</div>';
    whoisResult.dataset.text = '';
    return;
  }
  let domain = raw.replace(/^https?:\/\//, '').replace(/\/.+$/, '').trim();
  if (!isValidDomain(domain)) {
    whoisResult.innerHTML = '<div style="color:#ef4444;padding:1rem">❌ 域名格式无效，例如：example.com</div>';
    whoisResult.dataset.text = '';
    return;
  }
  domainInput.value = domain;

  whoisResult.innerHTML = '<div style="color:var(--text-secondary);text-align:center;padding:2rem 1rem">⏳ 正在通过 RDAP 查询 ' + escHtml(domain) + ' ...</div>';
  whoisResult.dataset.text = '';
  whoisBtn.disabled = true;
  whoisBtn.textContent = '⏳ 查询中...';

  try {
    let rdapUrl = 'https://rdap.org/domain/' + encodeURIComponent(domain);
    let resp;
    try {
      resp = await fetch(rdapUrl, { method: 'GET', mode: 'cors' });
    } catch (e) {
      const known = pickRdap(domain);
      if (known) {
        try {
          rdapUrl = known + encodeURIComponent(domain);
          resp = await fetch(rdapUrl, { method: 'GET', mode: 'cors' });
        } catch (e2) {
          resp = null;
        }
      } else {
        resp = null;
      }
    }
    if (!resp) {
      throw new Error('无法连接 RDAP 服务器（可能是 CORS 限制或网络问题）');
    }
    if (resp.status === 404) {
      throw new Error('该域名未注册或不支持 RDAP');
    }
    if (!resp.ok) {
      throw new Error('RDAP 服务器返回 ' + resp.status);
    }
    const data = await resp.json();
    whoisResult.innerHTML = renderRdap(domain, data);
    whoisResult.dataset.text = 'Domain: ' + domain + '\n\n--- RDAP Response ---\n' + JSON.stringify(data, null, 2);
  } catch (e) {
    const msg = (e && e.message) ? e.message : String(e);
    const hint = 'CORS 限制下浏览器无法直连 WHOIS 端口 43。请点击下方按钮到外部查询，或在终端运行 <code style="background:var(--bg);padding:0 .3rem;border-radius:3px">whois ' + escHtml(domain) + '</code>。';
    whoisResult.innerHTML = renderError(domain, msg, hint);
    whoisResult.dataset.text = 'Query failed for ' + domain + ': ' + msg;
  } finally {
    whoisBtn.disabled = false;
    whoisBtn.textContent = '🔍 查询 Whois / RDAP';
  }
}

whoisBtn.addEventListener('click', queryWhois);
domainInput.addEventListener('keydown', function (e) { if (e.key === 'Enter') queryWhois(); });

document.getElementById('presetEx').addEventListener('click', function () { domainInput.value = 'example.com'; queryWhois(); });
